select jsonb_build_object(
  'tables', (select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('profiles','program_families','content_items','archive_sources','daily_schedules','schedule_items','playout_history')),
  'policies', (select jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'command',cmd) order by tablename,policyname) from pg_policies where schemaname='public' and tablename in ('profiles','program_families','content_items','archive_sources','daily_schedules','schedule_items','playout_history')),
  'grants', (select jsonb_agg(jsonb_build_object('role',grantee,'table',table_name,'privilege',privilege_type) order by grantee,table_name,privilege_type) from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated') and table_name in ('profiles','program_families','content_items','archive_sources','daily_schedules','schedule_items','playout_history')),
  'functions', jsonb_build_object('anon_is_admin',has_function_privilege('anon','public.is_admin()','EXECUTE'),'authenticated_is_admin',has_function_privilege('authenticated','public.is_admin()','EXECUTE'),'anon_handle_new_user',has_function_privilege('anon','public.handle_new_user()','EXECUTE'),'authenticated_handle_new_user',has_function_privilege('authenticated','public.handle_new_user()','EXECUTE')),
  'trigger', (select pg_get_triggerdef(oid) from pg_trigger where tgrelid='auth.users'::regclass and not tgisinternal limit 1)
);
